{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/luuna-ai/luuna-missions/config.schema.json",
  "title": "Missions project config",
  "description": "Schema for .luuna/missions/config.yaml. Consumed by schema-driven configuration UIs; emit via `luuna-missions config schema`.",
  "type": "object",
  "required": [
    "project",
    "version"
  ],
  "additionalProperties": false,
  "properties": {
    "project": {
      "type": "string",
      "minLength": 1,
      "title": "Project name",
      "description": "Used as the prefix for issue IDs (e.g. `<project>-a1b2`)."
    },
    "version": {
      "type": "string",
      "title": "Config schema version",
      "description": "Internal version tag for the config layout. Bumped when the schema breaks.",
      "default": "1"
    },
    "max_plan_depth": {
      "type": "integer",
      "minimum": 1,
      "title": "Max plan depth",
      "description": "Display-only depth limit for `luuna-missions plan show` recursion through nested sub-plans.",
      "default": 3
    },
    "plan_templates": {
      "type": "object",
      "title": "Custom plan templates",
      "description": "Map of template name → template definition. Overrides the built-in `feature`, `bug`, and `refactor` templates when names collide.",
      "additionalProperties": {
        "$ref": "#/$defs/PlanTemplate"
      },
      "examples": [
        {
          "feature": {
            "sections": {
              "context": {
                "required": true,
                "kind": "text",
                "min_length": 50,
                "prompt": "Why does this work need to happen? What problem or opportunity drives it?"
              },
              "approach": {
                "required": true,
                "kind": "text",
                "prompt": "What's the chosen approach, and why this over alternatives?"
              },
              "alternatives": {
                "required": false,
                "kind": "list",
                "item": {
                  "name": {
                    "required": true,
                    "kind": "text",
                    "prompt": ""
                  },
                  "rejected_because": {
                    "required": true,
                    "kind": "text",
                    "prompt": ""
                  }
                },
                "prompt": "What other approaches were considered and rejected?"
              },
              "steps": {
                "required": true,
                "kind": "steps",
                "min": 2,
                "prompt": "Decompose into ordered, independent implementation steps. Each becomes a child seed."
              },
              "risks": {
                "required": false,
                "kind": "list",
                "item": "text",
                "atlas_source": "failure",
                "prompt": "What could go wrong? Known failure modes from prior work are pre-filled when luuna-atlas is available."
              },
              "acceptance": {
                "required": true,
                "kind": "list",
                "item": "text",
                "min": 1,
                "prompt": "Concrete, verifiable conditions for plan completion."
              }
            },
            "description": "New capability or significant change. Default for type: feature."
          },
          "bug": {
            "sections": {
              "context": {
                "required": true,
                "kind": "text",
                "prompt": "Why does fixing this matter? Who is affected and how?"
              },
              "reproduction": {
                "required": true,
                "kind": "text",
                "min_length": 50,
                "prompt": "Concrete steps to reproduce. Inputs, environment, observed vs. expected."
              },
              "root_cause": {
                "required": true,
                "kind": "text",
                "min_length": 50,
                "prompt": "What's actually broken? Trace the defect to its source, not just the symptom."
              },
              "approach": {
                "required": true,
                "kind": "text",
                "prompt": "Chosen fix and the rationale for it over alternatives."
              },
              "steps": {
                "required": true,
                "kind": "steps",
                "min": 1,
                "prompt": "Ordered fix steps. Each becomes a child seed."
              },
              "acceptance": {
                "required": true,
                "kind": "list",
                "item": "text",
                "min": 1,
                "prompt": "Verifiable conditions: regression test, behavior, etc."
              }
            },
            "description": "Defect fix. Adds reproduction and root_cause sections. Default for type: bug."
          },
          "refactor": {
            "sections": {
              "context": {
                "required": true,
                "kind": "text",
                "prompt": "Why this refactor? What pain does it relieve?"
              },
              "behavior_invariant": {
                "required": true,
                "kind": "text",
                "min_length": 50,
                "prompt": "The contract that MUST remain equal across the refactor. Be specific — this is what acceptance tests verify."
              },
              "approach": {
                "required": true,
                "kind": "text",
                "prompt": "Chosen restructuring strategy."
              },
              "steps": {
                "required": true,
                "kind": "steps",
                "min": 1,
                "prompt": "Ordered restructuring steps. Each becomes a child seed."
              },
              "acceptance": {
                "required": true,
                "kind": "list",
                "item": "text",
                "min": 1,
                "prompt": "How we'll verify the invariant is preserved."
              }
            },
            "description": "Internal restructuring. Adds behavior_invariant (must stay equal). Opt-in via --template refactor."
          }
        }
      ]
    }
  },
  "$defs": {
    "PlanTemplate": {
      "type": "object",
      "required": [
        "sections"
      ],
      "additionalProperties": false,
      "properties": {
        "description": {
          "type": "string",
          "title": "Description",
          "description": "Human-readable summary shown in `luuna-missions plan templates`."
        },
        "sections": {
          "type": "object",
          "title": "Sections",
          "description": "Map of section name → spec. Each section becomes a field in the plan submission.",
          "additionalProperties": {
            "$ref": "#/$defs/SectionSpec"
          }
        }
      }
    },
    "SectionSpec": {
      "type": "object",
      "required": [
        "required",
        "kind",
        "prompt"
      ],
      "additionalProperties": false,
      "properties": {
        "required": {
          "type": "boolean",
          "title": "Required",
          "description": "Whether this section must be present in the plan submission."
        },
        "kind": {
          "title": "Kind",
          "description": "`text` for free text, `list` for an array, `steps` for an ordered step list, or an object describing nested sub-fields.",
          "oneOf": [
            {
              "type": "string",
              "enum": [
                "text",
                "list",
                "steps"
              ]
            },
            {
              "type": "object",
              "additionalProperties": {
                "$ref": "#/$defs/SectionSpec"
              }
            }
          ]
        },
        "prompt": {
          "type": "string",
          "title": "Prompt",
          "description": "Question or instruction shown to the LLM when filling this section."
        },
        "min_length": {
          "type": "integer",
          "minimum": 0,
          "title": "Minimum length",
          "description": "Minimum character count when `kind` is `text`."
        },
        "min": {
          "type": "integer",
          "minimum": 0,
          "title": "Minimum items",
          "description": "Minimum item count when `kind` is `list` or `steps`."
        },
        "item": {
          "title": "Item shape",
          "description": "When `kind` is `list`, the per-item shape: `text` for strings or an object spec for structured items.",
          "oneOf": [
            {
              "type": "string",
              "const": "text"
            },
            {
              "type": "object",
              "additionalProperties": {
                "$ref": "#/$defs/SectionSpec"
              }
            }
          ]
        },
        "atlas_source": {
          "type": "string",
          "title": "Atlas source",
          "description": "Optional record type (e.g. `failure`, `decision`) seeded into `prior_art` when emitting a plan prompt."
        }
      }
    }
  }
}
